<div class="page-title"><div><em>BANKING</em><h1>My accounts</h1><p>View, open and fund all your NorthWest accounts.</p></div><button class="btn" data-modal="account-modal">+ Open new account</button></div><div class="account-grid"><?php foreach($accounts as $i=>$a):?><article class="account-card <?=$i%2?'teal':''?>"><small><?=strtoupper($a['type'])?> · <?=$a['currency']?></small><h3><?=html_escape($a['name'])?></h3><span>•••• <?=substr($a['account_number'],-4)?></span><strong><?=money($a['available_balance'],$a['currency'])?></strong><p>Available balance <b>›</b></p><button class="btn card-deposit" data-account-id="<?=$a['id']?>" data-account-name="<?=html_escape($a['name'])?>">↓ Deposit</button></article><?php endforeach?><article class="add-card"><i>+</i><h3>Add another account</h3><p>Explore checking, savings and investment options.</p><button data-modal="account-modal">Explore accounts</button></article></div><section class="panel"><div class="panel-head"><div><h2>Account summary</h2><p>Combined balances across your products</p></div></div><div class="summary"><div><span>Total assets</span><b><?=money(array_sum(array_column($accounts,'available_balance')))?></b></div><div><span>Active accounts</span><b><?=count($accounts)?></b></div><div><span>Primary currency</span><b>USD</b></div><div><span>Interest earned</span><b>$0.00</b></div></div></section>
<dialog id="account-modal"><div class="dialog-head"><h2>Open a new account</h2><button data-close>×</button></div><?=form_open('accounts/create')?><label>Account name</label><input name="name" placeholder="e.g. Travel savings"><div class="form-grid"><div><label>Type</label><select name="type"><option value="checking">Checking</option><option value="savings">Savings</option><option value="investment">Investment</option></select></div><div><label>Currency</label><select name="currency"><option value="USD">USD</option><option value="EUR">EUR</option><option value="GBP">GBP</option></select></div></div><label>Opening deposit (optional)</label><input name="opening_balance" type="number" step="0.01" min="0" placeholder="0.00"><button class="btn wide">Open account</button></form></dialog>
<dialog id="deposit-modal"><div class="dialog-head"><h2>Make a deposit</h2><button data-close>×</button></div><?=form_open('accounts/deposit')?><input type="hidden" name="account_id" id="deposit-account-id"><label>Account</label><input id="deposit-account-name" disabled><label>Amount</label><input name="amount" type="number" step="0.01" min="0.01" required placeholder="0.00"><button class="btn wide">Complete deposit</button></form></dialog>
<script>document.querySelectorAll('.card-deposit').forEach(function(b){b.addEventListener('click',function(){document.getElementById('deposit-account-id').value=b.dataset.accountId;document.getElementById('deposit-account-name').value=b.dataset.accountName;document.getElementById('deposit-modal').showModal();});});</script>
